class EventTicket5{private static int nextId=1000;private final String ticketId;protected double balanceDue;static{nextId=1000;}EventTicket5(double p){if(p<=0)throw new IllegalArgumentException();ticketId="TCK-"+(++nextId);balanceDue=p;}String getTicketId(){return ticketId;}static int getTicketsIssued(){return nextId-1000;}boolean isValidPromoCode(String c){if(c==null||c.length()!=5||c.charAt(0)!='F'||!Character.isDigit(c.charAt(1))||!Character.isDigit(c.charAt(2))||!Character.isDigit(c.charAt(3))||!Character.isUpperCase(c.charAt(4)))return false;return true;}void pay(double a){if(a>0)balanceDue=Math.max(0,balanceDue-a);}void pay(double a,String mode){pay(a);}}
class GroupTicket extends EventTicket5{int groupSize;GroupTicket(double p,int n){super(p);if(n<=0)throw new IllegalArgumentException();groupSize=n;}}
public class Problem5{static String processNightlySettlement(EventTicket5[] a){int p=0,n=0,g=0,i=0;if(a!=null)for(EventTicket5 t:a){if(t==null){n++;continue;}p++;if(t instanceof GroupTicket)g++;else i++;}return p+" processed | "+n+" null skipped | "+g+" group | "+i+" individual";}public static void main(String[]x){System.out.println(processNightlySettlement(new EventTicket5[]{new GroupTicket(1000,4),null,new EventTicket5(500)}));}}
